// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }
    function testFuzz_property(uint256 v1, uint256 v2, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(v1 != v2);
        vm.startPrank(actor);
        bool ok1;
        try c.SetMinSum(v1) { ok1 = true; } catch { ok1 = false; }
        bool ok2;
        try c.SetMinSum(v2) { ok2 = true; } catch { ok2 = false; }
        vm.stopPrank();
        assertTrue(ok1 && ok2 && c.MinSum() == v2);
    }
}
